import Foundation

/// One line of a config file: its text exactly as in the file, its line terminator, and what it means.
public struct ConfigLine: Equatable, Sendable {
    /// The line without its terminator, exactly as in the file (or as regenerated by an edit).
    public private(set) var text: String
    /// "\n", "\r\n", "\r" (or another Unicode line break) as in the file; "" for the last line.
    public internal(set) var terminator: String
    /// Interpretation of `text` (same rules as `APOParser`).
    public private(set) var kind: LineKind

    public init(text: String, terminator: String = "") {
        self.text = text
        self.terminator = terminator
        self.kind = LineInterpreter.interpret(text)
    }

    mutating func setText(_ t: String) {
        text = t
        kind = LineInterpreter.interpret(t)
    }

    /// The command, whether active or commented out.
    public var anyCommand: ConfigCommand? {
        switch kind {
        case .command(let c): return c
        case .comment(let c): return c
        default: return nil
        }
    }
}

/// A config file as an ordered list of lines that serialises back to the original bytes when unmodified.
///
/// Editing a line regenerates only that line, in canonical Equalizer APO syntax; every other line keeps
/// its text and terminator. The text encoding (UTF-8 with or without BOM, UTF-16 LE/BE with BOM) and the
/// line-ending style are kept. A file whose bytes cannot be reproduced exactly from decoded text (invalid
/// UTF-8, for example) is loaded `readOnly`: it can be shown and evaluated but not edited.
public struct ConfigDocument: Equatable, Sendable {
    public enum Encoding: String, Equatable, Sendable { case utf8, utf8BOM, utf16LE, utf16BE }

    public private(set) var encoding: Encoding
    public private(set) var lines: [ConfigLine]
    /// Terminator used for lines added by edits (the file's first terminator, else "\n").
    public private(set) var newline: String
    /// True when the bytes could not be decoded losslessly; `data()` then returns the original bytes.
    public let readOnly: Bool
    private let originalData: Data?

    public enum EditError: Error, Equatable { case readOnly, badIndex, notACommandComment }

    /// Decode a file's bytes. Never fails: undecodable bytes give a `readOnly` document whose text is the
    /// lossy decoding `APOParser` uses.
    public init(data: Data) {
        let bytes = [UInt8](data)
        var enc = Encoding.utf8
        var text: String?
        if bytes.count >= 2, bytes[0] == 0xFF, bytes[1] == 0xFE {
            enc = .utf16LE
            if let s = String(data: Data(bytes[2...]), encoding: .utf16LittleEndian),
               s.data(using: .utf16LittleEndian) == Data(bytes[2...]) { text = s }
        } else if bytes.count >= 2, bytes[0] == 0xFE, bytes[1] == 0xFF {
            enc = .utf16BE
            if let s = String(data: Data(bytes[2...]), encoding: .utf16BigEndian),
               s.data(using: .utf16BigEndian) == Data(bytes[2...]) { text = s }
        } else {
            var body = bytes[...]
            if bytes.count >= 3, bytes[0] == 0xEF, bytes[1] == 0xBB, bytes[2] == 0xBF { enc = .utf8BOM; body = bytes[3...] }
            let s = String(decoding: body, as: UTF8.self)
            if Array(s.utf8) == Array(body) { text = s }
        }
        encoding = enc
        if let text {
            readOnly = false
            originalData = nil
            lines = ConfigDocument.split(text)
        } else {
            readOnly = true
            originalData = data
            lines = ConfigDocument.split(APOParser.decode(data))
        }
        newline = lines.first(where: { !$0.terminator.isEmpty })?.terminator ?? "\n"
    }

    /// A document from text (UTF-8 unless stated).
    public init(text: String, encoding: Encoding = .utf8) {
        self.encoding = encoding
        readOnly = false
        originalData = nil
        lines = ConfigDocument.split(text)
        newline = lines.first(where: { !$0.terminator.isEmpty })?.terminator ?? "\n"
    }

    /// Split exactly like `APOParser` (every `Character.isNewline` ends a line; CRLF is one break), so line
    /// numbers match its warnings. The last element has terminator "" (empty text if the file ends with a break).
    static func split(_ text: String) -> [ConfigLine] {
        var out: [ConfigLine] = []
        var cur = ""
        for ch in text {
            if ch.isNewline { out.append(ConfigLine(text: cur, terminator: String(ch))); cur = "" }
            else { cur.append(ch) }
        }
        out.append(ConfigLine(text: cur, terminator: ""))
        return out
    }

    /// The whole text (terminators included, no BOM).
    public var text: String { lines.map { $0.text + $0.terminator }.joined() }

    /// File bytes in the document's encoding (with BOM where the original had one).
    public func data() -> Data {
        if readOnly, let d = originalData { return d }
        let t = text
        switch encoding {
        case .utf8: return Data(t.utf8)
        case .utf8BOM: return Data([0xEF, 0xBB, 0xBF]) + Data(t.utf8)
        case .utf16LE: return Data([0xFF, 0xFE]) + (t.data(using: .utf16LittleEndian) ?? Data())
        case .utf16BE: return Data([0xFE, 0xFF]) + (t.data(using: .utf16BigEndian) ?? Data())
        }
    }

    /// Index at which `append` inserts: before a trailing empty line (the file's final line break), else at the end.
    public var appendIndex: Int {
        if let last = lines.last, last.text.isEmpty, lines.count > 0 { return lines.count - 1 }
        return lines.count
    }

    // MARK: editing (each keeps every other line byte for byte)

    /// Replace the text of one line (its terminator is kept).
    public mutating func setLineText(_ text: String, at i: Int) throws {
        guard !readOnly else { throw EditError.readOnly }
        guard lines.indices.contains(i) else { throw EditError.badIndex }
        precondition(!text.contains(where: { $0.isNewline }), "line text must not contain line breaks")
        lines[i].setText(text)
    }

    /// Replace line `i` with `command` in canonical syntax. Leading indentation of the old line is kept.
    public mutating func setCommand(_ command: ConfigCommand, at i: Int) throws {
        guard lines.indices.contains(i) else { throw EditError.badIndex }
        let old = lines[i].text
        let indent = String(old.prefix(while: { $0 == " " || $0 == "\t" }))
        if case .comment = lines[i].kind {
            // keep it a comment: regenerate the commented command
            try setLineText(indent + "# " + command.canonicalText, at: i)
        } else {
            try setLineText(indent + command.canonicalText, at: i)
        }
    }

    /// Comment a line out (prefix "# ") or back in (remove the leading "#" and the spaces after it). Enabling
    /// is only allowed when the commented text is a valid command.
    public mutating func setCommented(_ commented: Bool, at i: Int) throws {
        guard lines.indices.contains(i) else { throw EditError.badIndex }
        let t = lines[i].text
        let indent = String(t.prefix(while: { $0 == " " || $0 == "\t" }))
        let body = t.dropFirst(indent.count)
        switch lines[i].kind {
        case .comment(let c):
            if commented { return }
            guard c != nil else { throw EditError.notACommandComment }
            let inner = body.dropFirst().drop(while: { $0 == " " || $0 == "\t" })
            try setLineText(indent + inner, at: i)
        case .blank:
            return
        default:
            if !commented { return }
            try setLineText(indent + "# " + body, at: i)
        }
    }

    /// Insert a line before index `i` (`i == lines.count` appends after the last line).
    public mutating func insertLine(_ text: String, at i: Int) throws {
        guard !readOnly else { throw EditError.readOnly }
        guard i >= 0, i <= lines.count else { throw EditError.badIndex }
        lines.insert(ConfigLine(text: text, terminator: newline), at: min(i, appendIndex))
        normalizeTerminators()
    }

    public mutating func insertCommand(_ c: ConfigCommand, at i: Int) throws { try insertLine(c.canonicalText, at: i) }

    /// Append a command as a new line before the file's final line break (if any). Returns its index.
    @discardableResult
    public mutating func appendCommand(_ c: ConfigCommand) throws -> Int {
        let i = appendIndex
        try insertLine(c.canonicalText, at: i)
        return i
    }

    public mutating func removeLine(at i: Int) throws {
        guard !readOnly else { throw EditError.readOnly }
        guard lines.indices.contains(i) else { throw EditError.badIndex }
        lines.remove(at: i)
        if lines.isEmpty { lines = [ConfigLine(text: "")] }
        normalizeTerminators()
    }

    /// Move line `from` so that it ends up at index `to` (in the resulting array).
    public mutating func moveLine(from: Int, to: Int) throws {
        guard !readOnly else { throw EditError.readOnly }
        guard lines.indices.contains(from), lines.indices.contains(to) else { throw EditError.badIndex }
        let hasFinalBreak = lines.count > 1 && lines[lines.count - 1].text.isEmpty
        let maxIndex = hasFinalBreak ? lines.count - 2 : lines.count - 1
        guard from <= maxIndex else { throw EditError.badIndex }
        let dest = min(to, maxIndex)
        if from == dest { return }
        let l = lines.remove(at: from)
        lines.insert(l, at: dest)
        normalizeTerminators()
    }

    /// Invariant after structural edits: every line but the last has a terminator; the last has none.
    /// (A file that ends with a line break keeps its empty last line, which edits never move.)
    private mutating func normalizeTerminators() {
        for i in lines.indices {
            if i == lines.count - 1 { lines[i].terminator = "" }
            else if lines[i].terminator.isEmpty { lines[i].terminator = newline }
        }
    }
}
